(1510657, 199479, 5354, '<td valign="top">Not sure what you have done in post processing, feels like a paint filter has been applied. Not sure I like the effect</td>', 'Not sure what you have done in post processing, feels like a paint filter has been applied. Not sure I like the effect', '2005-07-06 05:31:02.000000', NULL, 1),
(1510658, 198956, 31885, '<td valign="top">Nice one, too bad about the shadow!</td>', 'Nice one, too bad about the shadow!', '2005-07-06 05:31:06.000000', NULL, 1),
