(1512311, 198701, 2000, '<td valign="top">Water droplet on a spider web?  Very cool shot, but I personally would like to see the web a bit more clearly.  Even thought the web is not the main element, the leading lines of it would help IMO.</td>', 'Water droplet on a spider web?  Very cool shot, but I personally would like to see the web a bit more clearly.  Even thought the web is not the main element, the leading lines of it would help IMO.', '2005-07-06 13:46:22.000000', NULL, 1),
(1512313, 200742, 39664, '<td valign="top">I love this!  Way cool!  A 10 in my book!</td>', 'I love this!  Way cool!  A 10 in my book!', '2005-07-06 13:46:36.000000', NULL, 1),
(1512314, 200189, 1024, '<td valign="top">This is precious, and sure to become a family favorite.</td>', 'This is precious, and sure to become a family favorite.', '2005-07-06 13:46:38.000000', NULL, 1),
