(1512377, 200292, 39664, '<td valign="top">I think I would have liked this more in color but that is just me.</td>', 'I think I would have liked this more in color but that is just me.', '2005-07-06 13:55:31.000000', NULL, 1),
(1512378, 200120, 35044, '<td valign="top">colours are washed out here - needs to bve balanced with a colour cast.  Prob less blue green and more red tones.</td>', 'colours are washed out here - needs to bve balanced with a colour cast.  Prob less blue green and more red tones.', '2005-07-06 13:55:51.000000', NULL, 1),
