(1514805, 200717, 39752, '<td valign="top">nice colors. looks bit out of focus though.</td>', 'nice colors. looks bit out of focus though.', '2005-07-07 01:57:15.000000', NULL, 1),
(1514808, 198295, 3669, '<td valign="top">Very cute photo and good take on the challenge.  I''m a sucker for cuteness.  The lighting is perfect with good placement of your subject.  My only complaint...I''d like to see a little bit sharper focus.  9</td>', 'Very cute photo and good take on the challenge.  I''m a sucker for cuteness.  The lighting is perfect with good placement of your subject.  My only complaint...I''d like to see a little bit sharper focus.  9', '2005-07-07 01:58:49.000000', NULL, 1),
