INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1521287, 200115, 35931, '<td valign="top">Nice job.  You can really see the action of the mower.  And there''s something about the way the guy is walking.</td>', 'Nice job.  You can really see the action of the mower.  And there''s something about the way the guy is walking.', '2005-07-09 15:10:22.000000', NULL, 1),
(1521291, 199382, 35931, '<td valign="top">Sharp.</td>', 'Sharp.', '2005-07-09 15:11:36.000000', NULL, 1),
(1521300, 199368, 23053, '<td valign="top">Well executed close-up/macro.  The subject is really interesting and beautiful.  The image seems to have a blue-ish cast but it is a minor distraction.  Of course, I wasn''t there, so maybe this is how it looks.  Good job and good luck.</td>', 'Well executed close-up/macro.  The subject is really interesting and beautiful.  The image seems to have a blue-ish cast but it is a minor distraction.  Of course, I wasn''t there, so maybe this is how it looks.  Good job and good luck.', '2005-07-09 15:19:00.000000', NULL, 1),
(1521304, 200314, 23053, '<td valign="top">The lighting here could be better.  Perhaps mulitple lights, or if you wanted window light, a different time of day.  Basically, the photo is darker than I feel it should be.</td>', 'The lighting here could be better.  Perhaps mulitple lights, or if you wanted window light, a different time of day.  Basically, the photo is darker than I feel it should be.', '2005-07-09 15:20:43.000000', NULL, 1),
(1521319, 200198, 9255, '<td valign="top">Watch your background</td>', 'Watch your background', '2005-07-09 15:32:10.000000', NULL, 1),
(1521333, 198634, 36043, '<td valign="top">Interesting concept.  Midtones appear muddy  (highlights are almost blown) - perhaps color space is not sRGB or gamma issue?</td>', 'Interesting concept.  Midtones appear muddy  (highlights are almost blown) - perhaps color space is not sRGB or gamma issue?', '2005-07-09 15:36:57.000000', NULL, 1),
(1521343, 200454, 36043, '<td valign="top">Great idea - use some reflectors for softer lighting</td>', 'Great idea - use some reflectors for softer lighting', '2005-07-09 15:38:27.000000', NULL, 1),
(1521346, 198295, 39111, '<td valign="top">a bit flat, could use more contrast, perhapst some levels adjustments to give the cat a bit more punch.</td>', 'a bit flat, could use more contrast, perhapst some levels adjustments to give the cat a bit more punch.', '2005-07-09 15:39:05.000000', NULL, 1),
